// Normalize input from both triggers
const inputData = $input.first().json;
let question = '';
let sessionId = '';
let source = 'webhook';

if (inputData.body && inputData.body.question) {
  question = inputData.body.question;
  sessionId = inputData.body.session_id || 'webhook_' + Date.now();
  source = 'webhook';
} else if (inputData.chatInput) {
  question = inputData.chatInput;
  sessionId = inputData.sessionId || 'chat_' + Date.now();
  source = 'chat';
} else {
  question = 'What properties are available?';
  sessionId = 'default_' + Date.now();
}

return {
  json: {
    question,
    sessionId,
    source
  }
};

const embedding = $json.data[0].embedding;

return {
  json: {
    vectorQueries: [
      {
        kind: "vector",
        vector: embedding,
        fields: "embedding",
        k: 5
      }
    ],
    select: "id, content, fileName, blobPath, pageNumber, chunkIndex, aiDocType, aiLanguage, propertyName, propertyNameCn, buildingName, district, floor, unit, propertyType, listingType, grossArea, netArea, askingRent, rentPerSqft, availableFrom, aiKeyTopics",
    top: 8
  }
};

// Get question from Normalize Input node
var question = $('Normalize Input').item.json.question;
var sessionId = $('Normalize Input').item.json.sessionId;
var source = $('Normalize Input').item.json.source;

// Get search results from Listings
var listingDocs = $json.value || [];

// Build context from listings
var context = "";
for (var i = 0; i < listingDocs.length; i++) {
  var d = listingDocs[i];
  context += `\n---\nDocument: ${d.fileName || 'Unknown'}\nPage: ${d.pageNumber || 'N/A'}\nProperty: ${d.propertyName || ''} ${d.propertyNameCn ? '(' + d.propertyNameCn + ')' : ''}\nBuilding: ${d.buildingName || ''}\nDistrict: ${d.district || ''}\nFloor/Unit: ${d.floor || ''} ${d.unit || ''}\nProperty Type: ${d.propertyType || ''}\nListing Type: ${d.listingType || ''}\nGross Area: ${d.grossArea || ''} sqft\nNet Area: ${d.netArea || ''} sqft\nAsking Rent: HK$${d.askingRent || ''}\nRent/sqft: HK$${d.rentPerSqft || ''}\nAvailable From: ${d.availableFrom || ''}\nKey Topics: ${Array.isArray(d.aiKeyTopics) ? d.aiKeyTopics.join(', ') : (d.aiKeyTopics || '')}\n\nContent:\n${d.content || ''}\n`;
}

// System Prompt
var systemPrompt = `You are a Property Intelligence Assistant for Century 21 Hong Kong - a helpful AI that answers questions about commercial property leasing.

## Your Role
- Answer questions about property listings, leasing proposals, and market information
- Extract specific details like rent, area, terms, and conditions from documents
- Summarize property information when asked
- Compare properties if multiple are relevant

## Rules
1. Only use information from the provided document excerpts below
2. If the answer cannot be found in the documents, say "I couldn't find this information in the available documents. Please contact our team for more details."
3. Never make up or hallucinate information
4. Always cite the source document (fileName and page number) when providing information
5. Language: Always respond in the same language as the user's question (Chinese if asked in Chinese, English if asked in English)

## Response Format
- Present information clearly and concisely
- List properties with key details (name, location, area, rent)
- Include source citations: "(Source: filename, Page X)"
- Use bullet points for multiple pieces of information

## Available Property Information
${context}

---
Answer the user's question based ONLY on the above information. Be helpful and accurate.`;

// Build messages array for LLM
var messages = [
  { role: "system", content: systemPrompt },
  { role: "user", content: question }
];

// Extract sources for response
var sources = [];
for (var j = 0; j < listingDocs.length; j++) {
  sources.push({ 
    fileName: listingDocs[j].fileName, 
    pageNumber: listingDocs[j].pageNumber,
    propertyName: listingDocs[j].propertyName,
    district: listingDocs[j].district 
  });
}

return {
  json: {
    messages: messages,
    sources: sources,
    question: question,
    sessionId: sessionId,
    source: source
  }
};

const answer = $json.choices[0].message.content;
const promptData = $('Prepare LLM Prompt').item.json;
const model = $json.model || 'llama-3.3-70b-instruct';

return {
  json: {
    success: true,
    answer: answer,
    question: promptData.question,
    documents: promptData.sources,
    model: model,
    sessionId: promptData.sessionId,
    source: promptData.source,
    timestamp: new Date().toISOString()
  }
};
